package com.orderflow.notification.service;import com.orderflow.notification.config.NotificationProperties;import com.orderflow.notification.domain.*;import com.orderflow.notification.dto.*;import com.orderflow.notification.error.NotificationDomainException;import com.orderflow.notification.repository.NotificationRepository;import com.orderflow.platform.error.ErrorCode;import io.micrometer.core.instrument.MeterRegistry;import java.time.*;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationQueryService{private final NotificationRepository repository;private final NotificationMapper mapper;private final NotificationProperties properties;private final MeterRegistry metrics;private final Clock clock;public NotificationQueryService(NotificationRepository r,NotificationMapper m,NotificationProperties p,MeterRegistry x,Clock c){repository=r;mapper=m;properties=p;metrics=x;clock=c;}@Transactional(readOnly=true)public PageResponse<NotificationResponse>list(UUID user,int page,int size,Boolean read,NotificationType type,String sort){Sort.Direction direction="asc".equalsIgnoreCase(sort)?Sort.Direction.ASC:Sort.Direction.DESC;Pageable p=PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,properties.maxPageSize())),Sort.by(direction,"createdAt"));Page<Notification>n=read!=null?repository.findByUserIdAndRead(user,read,p):type!=null?repository.findByUserIdAndType(user,type,p):repository.findByUserId(user,p);return new PageResponse<>(n.map(mapper::response).getContent(),n.getNumber(),n.getSize(),n.getTotalElements(),n.getTotalPages());}@Transactional(readOnly=true)public long unread(UUID user){return repository.countByUserIdAndReadFalse(user);}@Transactional public NotificationResponse read(UUID user,UUID id){Notification n=repository.findById(id).filter(x->x.getUserId().equals(user)).orElseThrow(this::notFound);if(n.markRead(Instant.now(clock)))metrics.counter("notifications_read_total").increment();return mapper.response(n);}@Transactional public int readAll(UUID user){int n=repository.markAllRead(user,Instant.now(clock));metrics.counter("notifications_read_total").increment(n);return n;}private NotificationDomainException notFound(){return new NotificationDomainException(HttpStatus.NOT_FOUND,ErrorCode.NOTIFICATION_NOT_FOUND,"Notification not found");}}
